import AppKit

/// Provider service that loads and caches the Smurfbar application icon across all environments
/// (bundled app, SPM CLI run, tests, settings window).
final class AppIconProvider {
    static let shared = AppIconProvider()

    private(set) var iconImage: NSImage?

    private init() {
        self.iconImage = Self.resolveAppIcon()
    }

    private static func resolveAppIcon() -> NSImage? {
        // 1. Try loading from main bundle resources
        if let bundleImage = NSImage(named: NSImage.Name("AppIcon")) {
            return bundleImage
        }

        if let pngURL = Bundle.main.url(forResource: "AppIcon", withExtension: "png"),
           let img = NSImage(contentsOf: pngURL) {
            return img
        }

        if let icnsURL = Bundle.main.url(forResource: "AppIcon", withExtension: "icns"),
           let img = NSImage(contentsOf: icnsURL) {
            return img
        }

        // 2. Try looking relative to main bundle resource path
        if let resourceURL = Bundle.main.resourceURL {
            let candidatePNG = resourceURL.appendingPathComponent("AppIcon.png")
            if let img = NSImage(contentsOf: candidatePNG) {
                return img
            }
            let candidateICNS = resourceURL.appendingPathComponent("AppIcon.icns")
            if let img = NSImage(contentsOf: candidateICNS) {
                return img
            }
        }

        // 3. Try looking in candidate directories relative to executable or current directory (dev/debug mode)
        let fileManager = FileManager.default
        var searchRoots: [URL] = []

        if let execURL = Bundle.main.executableURL {
            var dir = execURL.deletingLastPathComponent()
            for _ in 0..<5 {
                searchRoots.append(dir)
                dir = dir.deletingLastPathComponent()
            }
        }

        searchRoots.append(URL(fileURLWithPath: fileManager.currentDirectoryPath))

        for root in searchRoots {
            let candidates = [
                root.appendingPathComponent("Resources/AppIcon.png"),
                root.appendingPathComponent("Resources/AppIcon.icns"),
                root.appendingPathComponent("Sources/Smurfbar/Resources/AppIcon.png"),
                root.appendingPathComponent(".build/Smurfbar.app/Contents/Resources/AppIcon.png")
            ]
            for candidate in candidates {
                if fileManager.fileExists(atPath: candidate.path),
                   let img = NSImage(contentsOf: candidate) {
                    return img
                }
            }
        }

        // 4. Try NSApp applicationIconImage if valid and non-generic
        let appIcon = NSApp?.applicationIconImage
        if let appIcon = appIcon, appIcon.isValid, appIcon.size.width > 0 {
            return appIcon
        }

        // 5. Embedded fallback data
        if let embeddedData = Data(base64Encoded: embeddedBase64Icon, options: .ignoreUnknownCharacters),
           let img = NSImage(data: embeddedData) {
            return img
        }

        return nil
    }
}

private let embeddedBase64Icon = """

"""
